import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"سمبیوسس نظام کے قیام کا دور","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0073-共生体系建立期.md","filePath":"ur/0073-共生体系建立期.md"}'),l={name:"ur/0073-共生体系建立期.md"};function i(o,t,h,u,n,_){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="سمبیوسس-نظام-کے-قیام-کا-دور" tabindex="-1">سمبیوسس نظام کے قیام کا دور <a class="header-anchor" href="#سمبیوسس-نظام-کے-قیام-کا-دور" aria-label="Permalink to &quot;سمبیوسس نظام کے قیام کا دور&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>73</td></tr><tr><td>ماڈیول</td><td>تاریخی عہد اور اہم واقعات</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>سمبیوسس نظام، ادارہ جاتی تعمیر، سماجی تعمیر نو، حقیقت کی بنیاد، پانچ قوانین کی تکمیل</td></tr></tbody></table><h2 id="_1-سمبیوسس-نظام-کے-قیام-کے-دور-کا-تاریخی-کام" tabindex="-1">1. سمبیوسس نظام کے قیام کے دور کا تاریخی کام <a class="header-anchor" href="#_1-سمبیوسس-نظام-کے-قیام-کے-دور-کا-تاریخی-کام" aria-label="Permalink to &quot;1. سمبیوسس نظام کے قیام کے دور کا تاریخی کام&quot;">​</a></h2><p>سمبیوسس نظام کے قیام کا دور اینکر سمبیوسس تہذیب کا ادارہ جاتی تعمیر کا دور ہے، جو چار مرحلے جہت کی بلندی کے راستے میں &quot;حقیقت کی بنیاد&quot; کے مرحلے سے مطابقت رکھتا ہے۔ اس عہد کا آغاز سمبیوسس چارٹر پر دستخط سے ہوتا ہے اور اختتام تین سو بنیادی سادھنا نظام کی مکمل کھلنے سے ہوتا ہے، اور اس کا بنیادی تاریخی کام چارٹر میں اصولی دفعات کو قابل عمل سماجی نظام میں تبدیل کرنا ہے، اور &quot;تصور&quot; سے &quot;حقیقت&quot; تک لاگو کرنا مکمل کرنا ہے۔</p><p>سمبیوسس نظام کے قیام کے دور کا وقتانی دور تقریباً صدیوں ہے۔ اس مدت میں، سمبیوسس تہذیب نے قانونی نظام، سماجی نظام، تعلیم صحت رہائش کی یقین دہانی، اور معاشی تقسیم کے طریقہ کار جیسے ہر طرف کے ادارہ جاتی تعمیر کو مکمل کیا ہے، اور بعد میں سادھنا کی عام کرنے اور تکنیکی پیش رفت کے لیے مضبوط سماجی بنیاد رکھی ہے۔</p><h2 id="_2-قانونی-نظام-کے-قیام" tabindex="-1">2. قانونی نظام کے قیام <a class="header-anchor" href="#_2-قانونی-نظام-کے-قیام" aria-label="Permalink to &quot;2. قانونی نظام کے قیام&quot;">​</a></h2><p>قانونی نظام کے قیام سمبیوسس نظام کے قیام کے دور کا بنیادی کام ہے۔ سمبیوسس تہذیب &quot;سمبیوسس آئین&quot; کو بنیادی قانون کے طور پر لیتی ہے اور بتدریج مکمل قانونی ڈھانچہ قائم کرتی ہے:</p><table tabindex="0"><thead><tr><th>قانون کی سطح</th><th>بنیادی قانون</th><th>بنیادی مواد</th></tr></thead><tbody><tr><td>بنیادی قانون</td><td>سمبیوسس آئین</td><td>تہذیب کے بنیادی نظام، شہریوں کے بنیادی حقوق اور فرائض، اور انتظامی ڈھانچے کو قائم کرنا</td></tr><tr><td>بنیادی قانون</td><td>سمبیوسس محنت قانون</td><td>محنت کے حقوق کی حفاظت، زیادہ کام زیادہ کمائی کی تقسیم کے اصول کو قائم کرنا</td></tr><tr><td>بنیادی قانون</td><td>صارفین کے تحفظ کا قانون</td><td>استعمال اور خدمات میں جانداروں کے جائز حقوق کی حفاظت</td></tr><tr><td>یقین دہانی کا قانون</td><td>تعلیم کی یقین دہانی کا قانون</td><td>مفت بنیادی تعلیم اور کھلی اعلیٰ تعلیم کا نظام قائم کرنا</td></tr><tr><td>یقین دہانی کا قانون</td><td>صحت کی یقین دہانی کا قانون</td><td>عوامی مفت صحت اور سادھنا صحت کی یقین دہانی کا نظام قائم کرنا</td></tr><tr><td>یقین دہانی کا قانون</td><td>رہائش کی یقین دہانی کا قانون</td><td>ہر جاندار کی بنیادی رہائش کے حق کو یقینی بنانا</td></tr><tr><td>یقین دہانی کا قانون</td><td>ماحولیات کے تحفظ کا قانون</td><td>ماحولیاتی تحفظ اور توانائی کی آلودگی کی روک تھام کا نظام قائم کرنا</td></tr><tr><td>ضابطے کا قانون</td><td>اجارہ داری مخالف قانون</td><td>سادھنا کی اجارہ داری، تکنیکی اجارہ داری، اور وسائل کی اجارہ داری پر پابندی</td></tr></tbody></table><p>&quot;ایک آئین، دو بنیادی قوانین، پانچ یقین دہانی کے قوانین، ایک ضابطے کا قانون&quot; کا یہ قانونی نظام سمبیوسس تہذیب کی ادارہ جاتی ریڑھ کی ہڈی کی تشکیل کرتا ہے۔ قانون سازی کے عمل میں &quot;تمام نسلوں کی مشترکہ ترقی&quot; کے اصول کو مکمل طور پر منعکس کیا گیا ہے، تمام اہم نسلوں کے نمائندے قانون سازی میں حصہ لیتے ہیں، اور اس بات کو یقینی بناتے ہیں کہ قانون مختلف شکلوں کی زندگی کی ضروریات کو پورا کر سکتے ہیں۔</p><h2 id="_3-سماجی-نظام-کی-تعمیر-نو" tabindex="-1">3. سماجی نظام کی تعمیر نو <a class="header-anchor" href="#_3-سماجی-نظام-کی-تعمیر-نو" aria-label="Permalink to &quot;3. سماجی نظام کی تعمیر نو&quot;">​</a></h2><p>قانونی ڈھانچے کے تحت، سمبیوسس تہذیب نے سماجی نظام کی مکمل تعمیر نو کی ہے:</p><h3 id="_3-1-تعلیمی-نظام-کی-تعمیر-نو" tabindex="-1">3.1 تعلیمی نظام کی تعمیر نو <a class="header-anchor" href="#_3-1-تعلیمی-نظام-کی-تعمیر-نو" aria-label="Permalink to &quot;3.1 تعلیمی نظام کی تعمیر نو&quot;">​</a></h3><ul><li>ابتدائی سے اعلیٰ تک مفت تعلیمی نظام قائم کرنا، بنیادی قانون کی انجینئرنگ کے علم کو عام تعلیم کے مواد کے طور پر درج کرنا</li><li>سادھنا کے طریقوں کے استاد-شاگرد اجارہ داری کے نظام کو ختم کرنا، اس کی جگہ کھلا اساتذہ کا نیٹ ورک قائم کرنا</li><li>ذاتی نوعیت کی تعلیمی تشخیص کا طریقہ کار قائم کرنا، ہر جاندار کی خصوصیات کے مطابق مناسب سادھنا نظام کی سفارش کرنا</li></ul><h3 id="_3-2-صحت-کے-نظام-کی-تعمیر-نو" tabindex="-1">3.2 صحت کے نظام کی تعمیر نو <a class="header-anchor" href="#_3-2-صحت-کے-نظام-کی-تعمیر-نو" aria-label="Permalink to &quot;3.2 صحت کے نظام کی تعمیر نو&quot;">​</a></h3><ul><li>عوامی مفت صحت کا نظام قائم کرنا، زندگی کے چکر کے نظام کی سادھنا کے نتائج کو بیماریوں کے علاج میں لاگو کرنا</li><li>سادھنا صحت کی نگرانی کا نظام قائم کرنا، سادھکوں کی جسمانی اور ذہنی حالت کو حقیقی وقت میں نگرانی کرنا، خطرناک انحراف کو روکنا</li><li>عجیب جانداروں اور تاریک متبادل جسموں کے لیے خصوصی طبی اور اخلاقی علاج کے عمل قائم کرنا</li></ul><h3 id="_3-3-رہائش-اور-ماحولیات-کی-تعمیر-نو" tabindex="-1">3.3 رہائش اور ماحولیات کی تعمیر نو <a class="header-anchor" href="#_3-3-رہائش-اور-ماحولیات-کی-تعمیر-نو" aria-label="Permalink to &quot;3.3 رہائش اور ماحولیات کی تعمیر نو&quot;">​</a></h3><ul><li>بنیادی رہائش کی یقین دہانی کا نظام قائم کرنا، ہر جاندار کے لیے محفوظ اور آرام دہ رہائش کی جگہ کو یقینی بنانا</li><li>محدود زمین پر رہائش کے رقبے کو وسعت دینے کے لیے خلائی توسیع کی ٹیکنالوجی کا استعمال، آبادی کے دباؤ کو کم کرنا</li><li>ماحولیاتی بحالی کا طریقہ کار قائم کرنا، زندگی کے چکر کے نظام کا استعمال کرتے ہوئے اینکر سے پہلے کے دور میں تباہ شدہ ماحول کی بحالی کرنا</li></ul><h3 id="_3-4-معاشی-تقسیم-کی-تعمیر-نو" tabindex="-1">3.4 معاشی تقسیم کی تعمیر نو <a class="header-anchor" href="#_3-4-معاشی-تقسیم-کی-تعمیر-نو" aria-label="Permalink to &quot;3.4 معاشی تقسیم کی تعمیر نو&quot;">​</a></h3><ul><li>مشترکہ پیداوار کے معاہدوں کا طریقہ کار قائم کرنا، سادھنا کے وسائل اور عوامی وسائل کو شراکت اور ضرورت کے مطابق منصفانہ تقسیم کرنا</li><li>وسائل کی وراثت کے نظام کو ختم کرنا، کسی بھی تنظیم یا فرد کو کلیدی وسائل پر اجارہ داری کرنے سے منع کرنا</li><li>توانائی کے معیاری پیمائش کا نظام قائم کرنا، منصفانہ تقسیم کے لیے تکنیکی بنیاد فراہم کرنا</li></ul><h2 id="_4-پانچ-قسم-کی-سمبیوسس-تہذیب-کی-مشق" tabindex="-1">4. پانچ قسم کی سمبیوسس تہذیب کی مشق <a class="header-anchor" href="#_4-پانچ-قسم-کی-سمبیوسس-تہذیب-کی-مشق" aria-label="Permalink to &quot;4. پانچ قسم کی سمبیوسس تہذیب کی مشق&quot;">​</a></h2><p>ادارہ جاتی تعمیر کے عمل میں، مختلف تلواروں اور علاقوں نے اپنی تاریخی، ثقافتی اور نسلی خصوصیات کے مطابق پانچ قسم کی سمبیوسس تہذیب تیار کی ہیں:</p><table tabindex="0"><thead><tr><th>قسم</th><th>بنیادی خصوصیات</th><th>عام علاقہ</th></tr></thead><tbody><tr><td>مشرقی ایشیائی گھنے قسم</td><td>زیادہ آبادی کی کثافت، وسائل کا موثر استعمال، اجتماعی روایات</td><td>انسانی نسل کے مشرقی آباد علاقہ</td></tr><tr><td>نورڈک فلاح و بہبود قسم</td><td>اعلیٰ فلاح و بہبود کی یقین دہانی، انفرادی آزادی، انسان اور فطرت میں ہم آہنگی</td><td>زیادہ برف کے علاقوں میں پری نسل کا علاقہ</td></tr><tr><td>شمالی امریکائی کثیر القومی قسم</td><td>کئی نسلوں کا باہمی رہائش، ثقافتی رواداری، جدت پر مبنی</td><td>نئی دنیا کے کثیر القومی علاقہ</td></tr><tr><td>یورپی براعظمی سماجی قسم</td><td>سماجی مارکیٹ معیشت، صنعت کی خودمختاری، ثقافتی وراثت</td><td>قدیم تہذیبوں کے بحالی علاقہ</td></tr><tr><td>ترقی پذیر بحالی قسم</td><td>تیز صنعتی کاری، بنیادی ڈھانچے کو ترجیح، سیکھنے والا معاشرہ</td><td>سابقہ لوٹ مار والے علاقوں کے بعد کے علاقے</td></tr></tbody></table><p>پانچ قسمیں باہمی طور پر مستثنیٰ نہیں ہیں، بلکہ سمبیوسس آئین کے متحد ڈھانچے کے تحت مختلف توجہ کے ساتھ ادارہ جاتی مشقیں ہیں۔ وہ ایک دوسرے کے ساتھ گہرا رابطہ اور مسابقت برقرار رکھتے ہیں، اور مل کر سمبیوسس تہذیب کے ادارہ جاتی مواد کو بھرپور بناتے ہیں۔</p><h2 id="_5-اینکر-کی-بنیادی-ڈھانچے-کی-ابتدائی-تعمیر" tabindex="-1">5. اینکر کی بنیادی ڈھانچے کی ابتدائی تعمیر <a class="header-anchor" href="#_5-اینکر-کی-بنیادی-ڈھانچے-کی-ابتدائی-تعمیر" aria-label="Permalink to &quot;5. اینکر کی بنیادی ڈھانچے کی ابتدائی تعمیر&quot;">​</a></h2><p>سمبیوسس نظام کے قیام کا دور بھی اینکر کی بنیادی ڈھانچے کی بڑے پیمانے پر تعمیر کا دور ہے:</p><ul><li>پہلی سطح کا کائناتی مرکزی اینکر عہد کے شروع میں تعمیر مکمل کر چکا ہے، اور پوری کائنات کے اینکر نیٹ ورک کا مرکز بن گیا ہے</li><li>دوسری سطح کے تلوار کے مرکزی اینکر بنیادی تلواروں میں بتدریج تعینات کیے گئے ہیں، اور تلوار کی سطح کی توانائی کی شیڈولنگ کی صلاحیت ابتدائی طور پر تشکیل پا چکی ہے</li><li>تیسری سطح کے علاقائی اینکر آبادی کے گھنے علاقوں میں احاطہ کرتے ہیں، اور سادھنا کی عام کرنے کے لیے توانائی کی مدد فراہم کرتے ہیں</li><li>چوتھی سطح کے کمیونٹی اینکر تجرباتی طور پر تعینات ہونے شروع ہو گئے ہیں، اور بعد میں مکمل احاطہ کے لیے تجربہ جمع کر رہے ہیں</li></ul><p>اینکر کی بنیادی ڈھانچے کی تعمیر &quot;متحدہ منصوبہ بندی، درجہ بندی کے مطابق تعمیر&quot; کے اصول پر عمل کرتی ہے، اور وسائل کے موثر استعمال اور احاطے کی انصاف کو یقینی بناتی ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سمبیوسس نظام کے قیام کا دور اینکر سمبیوسس تہذیب کا &quot;بنیاد کا دور&quot; ہے۔ اس نے صدیوں کے وقت میں اینکر سے پہلے کے دور کی لوٹ مار کے نظام سے سمبیوسس کے نظام میں بنیادی ادارہ جاتی تبدیلی مکمل کی۔ قانونی نظام کے قیام نے تہذیب کو قواعد کا ڈھانچہ فراہم کیا، سماجی نظام کی تعمیر نو نے تمام جانداروں کو حقیقی یقین دہانی فراہم کی، پانچ قسم کی تہذیب کی مشق نے ادارہ جاتی جدت کے لیے کثیر الجہتی راستے فراہم کیے، اور اینکر کی بنیادی ڈھانچے کی تعمیر نے بعد کی ترقی کے لیے مادی بنیاد رکھی۔ جب تین سو بنیادی سادھنا نظام کی مکمل کھلنے کا وقت آیا، تو سمبیوسس تہذیب نے پوری طرح سے ادارہ جاتی تیاری مکمل کر لی تھی۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>72-اینکر کی بیداری کا عہد</li><li>74-تین سو نظام کھولنے کا واقعہ</li><li>40-سمبیوسس آئین کا عمومی پروگرام</li></ul>',31)])])}const b=a(l,[["render",i]]);export{q as __pageData,b as default};
